public class RethrowerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("parseOrWrap(\"123\")", 123, Rethrower.parseOrWrap("123"));
            check("parseOrWrap(\"-7\")", -7, Rethrower.parseOrWrap("-7"));
        } catch (Exception e) {
            check("valid input must not throw", "no exception", e.getClass().getSimpleName());
        }

        Throwable thrown = null;
        try {
            Rethrower.parseOrWrap("abc");
        } catch (Throwable t) {
            thrown = t;
        }
        check("bad input throws", true, thrown != null);
        check("exception type", "IllegalStateException",
                thrown == null ? "(none)" : thrown.getClass().getSimpleName());
        check("exception message", "bad input: abc",
                thrown == null ? "(none)" : thrown.getMessage());
        check("cause is the original NumberFormatException", "NumberFormatException",
                thrown == null || thrown.getCause() == null
                        ? "(none)" : thrown.getCause().getClass().getSimpleName());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

